import java.util.*;

class Solution {
    public boolean sameNotes(String a, String b) {
        return finalText(a).equals(finalText(b));
    }

    private String finalText(String s) {
        StringBuilder out = new StringBuilder();
        for (char ch : s.toCharArray()) {
            if (ch == '#') {
                if (out.length() > 0) out.deleteCharAt(out.length() - 1);
            } else {
                out.append(ch);
            }
        }
        return out.toString();
    }
}

